x_comment(x_fileExists,"(fileExists ?directory ?filename ?extension ?url) Matches a directory/filename/extension combination (possibly variablized) to the url(s) for one or more existing files.\nIf it is invoked with a bound path argument - this is effectively an existence test - the other arguments should be unbound (they cannot help specify anything in these cases, so why support them?).\nIf it is invoked with an unbound url argument, the directory argument needs to be bound (it's not going to search the file-system for you).\nAll other combinations are supported.  You can use it to enumerate all the files in a directory, or just the sketch files (sk), or just the files named Foo, or to extract the directory, file and extension from a url, as long as the file exists.") :- x_cid(a65b125cee84e8).
